                            interpolated_levels[:,1]=interp_func(time)
                            
                            time=time[cutoff:len(time)-cutoff]
                            conv=np.convolve(weights,interpolated_levels[:,1],'valid')
                            smoothed=999*ones((len(time),2))
                            smoothed[:,0]=time[:]
