def preproces_by_averaging(head_serie,stress_series,user_selected_time_period,flags,memory):  #this function prepares all the data for the time series analysis by averaging over a time period (day, week, bi-weekly, month, year)
    
    from scipy import interpolate
    from numpy.random import random_integers
    import numpy as np
    from datetime import datetime,date
    from matplotlib.dates import date2num, num2date
    
    ##### SECTION 1: read time series and store them in a temporary 'time_serie' dictionary and declare the data dictionary which will be the output of the whole function

    data={}#declare the data dictionary which is the main output of the function and will contain all preprocessed time series with corresponding metadata
    time_series_of_observations={}#declare the time_serie_of_observations dictionnary of observed time series (contain both the groundwater head to explain and the time series of explaining variables)
    list_of_explaining_stresses=stress_series.keys()
    explaining_time_series_names={}
    
    supported_time_periods=['DAY','WEEK','MONTH','YEAR']        #   list of supported time periods
    periods_length={'DAY':1,'WEEK':7,'MONTH':365/12,'YEAR':365.25}     #   (approximative) length of periods in days
    
    if flags['DINO']==0:
        time_series_of_observations['H_OBS']= read_head_serie(head_serie,flags)#read observed groundwater head series with series['H_OBS'][0] the time serie and series['H_OBS'][1] the associated metadata
    elif flags['DINO']==1:
        time_series_of_observations['H_OBS']= read_DINO_head_serie(head_serie,flags)

    
    error_messages=[]
    for STRESS in list_of_explaining_stresses:
        time_series_of_observations[STRESS]={}
        explaining_time_series_names[STRESS]=[]
        for file_path in stress_series[STRESS]:
            a=file_path.split('\\')#from the whole file name, we extract the base name of the well or other stress
            a=a[len(a)-1].split('.')
            name=a[0]
            time_series_of_observations[STRESS][name]= read_stress_serie(file_path,STRESS,flags) #stress_series are the sources ascii files
            explaining_time_series_names[STRESS].append(name)


    ##### SECTION 2: controle that time series are longer than 10 (this is arbitrary), have complete metadata and overlap in time 

    list_tmin=[]
    if len(time_series_of_observations['H_OBS'][0])<10:
        error_messages.append(head_serie.split('\\')[-1]+' :less than 10 measurements points')
        data['error']=error_messages
    if 'error' not in data:
        for u in time_series_of_observations:
            if u=='H_OBS':
                list_tmin.append(time_series_of_observations[u][0][0,0])
            else:
                for e in time_series_of_observations[u]:
                    list_tmin.append(time_series_of_observations[u][e][0][0,0]+memory[u])
        tmin=max(list_tmin)
        

        list_tmax=[]
        for u in time_series_of_observations:
            if u=='H_OBS':
                list_tmax.append(time_series_of_observations[u][0][-1,0])#collection of last time of each obervation serie
            else:
                for e in time_series_of_observations[u]:
                    list_tmax.append(time_series_of_observations[u][e][0][-1,0])#collection of last time of each obervation serie
        tmax=min(list_tmax)
    
        if time_series_of_observations['H_OBS'][1]=={}:
            error_messages.append(head_serie.split('\\')[-1]+': incomplete metadata')
            data['error']=error_messages
        else:
            data={'id':time_series_of_observations['H_OBS'][1]['name']}
    
        if tmax<tmin:
            error_messages.append(head_serie.split('\\')[-1]+': time series do not overlap')
            data['error']=error_messages
        
    #### SECTION 3: extract the part of the total time series which can be used in the analyse       
        if 'error' not in data:#if no error is detected in time series, proceed to the preprocessing of the time series
            
            selected={}#selected is a dictionary of extracted time series
            
            #extract time serie of groundwater heads
            tobs=time_series_of_observations['H_OBS'][0][:,0]#tobs is a vector of times of observations, expressed in day numbers
            mask=((tobs>=tmin)&(tobs<=tmax))#create a mask corresponding to observed data with time value within tmin and tmax defined in section 2
            selected['H_OBS']=time_series_of_observations['H_OBS'][0][mask,:]
            
            #extract time serie of stresses, the explaining variables (prec, evap, well, riv etc) 
            for STRESS in list_of_explaining_stresses:
                selected[STRESS]={}
                for e in explaining_time_series_names[STRESS]:      
                    tmin_stress=tmin-memory[STRESS]*1.5#give some marge when extracting the usefull part of the time serie to later alow select complete weeks, month or years
                    tmax_stress=tmax+memory[STRESS]*0.5#here also, give some marge when extracting the usefull part of the time serie
                    tobs=time_series_of_observations[STRESS][e][0][:,0]
                    mask=((tobs>=tmin_stress)&(tobs<=tmax_stress))#create a mask corresponding to observed data with time value within tmin and tmax of stress
                    selected[STRESS][e]=time_series_of_observations[STRESS][e][0][mask,:]                

    #### SECTION 4: check that the adequation of the time period chosen by the user 'user_selected_time_period'
    
            # If it occurs that the measurement interval of one of the series is longer than the chosen time period, replace it by a longer.
            #For example: if the user wish to average the series over a week but the pumping data are available as month cumulative sums,
            # then the averaging time period is automatically replaced by a month time period.
            
            #first, detect the longest time interval in the explaining series
            for STRESS in list_of_explaining_stresses:
                for e in explaining_time_series_names[STRESS]:
                    longest_time_interval=0
                    time_intervals=selected[STRESS][e][1:,0]-selected[STRESS][e][:-1,0]
                    max_interval=max(time_intervals)
                    if max_interval>longest_time_interval:
                        longest_time_interval=max_interval
                        
            #then, if the longerst time interval exceed by 20% the time interval chosen by the user, replace it by the shortest possible time period which is longer than all time intervals in the stress time series
            if longest_time_interval>1.2*periods_length[user_selected_time_period]:# give 20% marge to exceed the the user selected time interval
                list_of_longer_time_periods=[]
                for tperiod in periods_length:
                    if periods_length[tperiod]>0.8*longest_time_interval:#here also give a 20% margin over longest time interval
                        list_of_longer_time_periods.append(tperiod)
                user_selected_time_period=list_of_longer_time_periods[0]#take the shortest of the time intervals which are longer than the longest time interval of the measured stress series

    #### SECTION 5: determine the time intervals over which groundwater time series will be averaged 
            
            representative_times={}
            begin_time_intervals={}
            end_time_intervals={}
            
            #first, determine the representative times based on groundwater head; tmin and tmax as determined in section 2
            begin_datetime=datetime.fromordinal(int(tmin)-1)
            begin_datetime_tuple=begin_datetime.timetuple()
            begin_year=begin_datetime_tuple.tm_year
            begin_month=begin_datetime_tuple.tm_mon
            begin_day_of_the_week=begin_datetime_tuple.tm_wday#week day is zero for monday
            
            end_datetime=datetime.fromordinal(int(tmax))
            end_datetime_tuple=end_datetime.timetuple()
            end_year=end_datetime_tuple.tm_year
            end_month=end_datetime_tuple.tm_mon

            if user_selected_time_period=='DAY':
      
                tmin=int(tmin)+1#this is to make sure that the time interval begins on next monday
                tmax=int(tmax)
                begin_of_next_time_interval=tmin
                end_of_next_time_interval=tmin+1

                begin_time_intervals_list=[]
                end_time_intervals_list=[]
                
                while end_of_next_time_interval<=tmax:
                    begin_time_intervals_list.append(begin_of_next_time_interval)
                    end_time_intervals_list.append(end_of_next_time_interval)
                    begin_of_next_time_interval=end_of_next_time_interval
                    end_of_next_time_interval=end_of_next_time_interval  +1    

                
            elif user_selected_time_period=='WEEK':
      
                tmin=int(tmin)+(7-begin_day_of_the_week)#this is to make sure that the time interval begins on next monday
                tmax=int(tmax)-begin_day_of_the_week#this is to make sure that the time interval ends on last monday
                begin_of_next_time_interval=tmin
                end_of_next_time_interval=tmin+7

                begin_time_intervals_list=[]
                end_time_intervals_list=[]
                
                while end_of_next_time_interval<=tmax:
                    begin_time_intervals_list.append(begin_of_next_time_interval)
                    end_time_intervals_list.append(end_of_next_time_interval)
                    begin_of_next_time_interval=end_of_next_time_interval
                    end_of_next_time_interval=end_of_next_time_interval  +7
                #remove begin intervals if no measurement is available within it; this is to avoid problems when interpolating
                s=0
                while s==0:
                    mask=(selected['H_OBS'][:,0]>=begin_time_intervals_list[0])&(selected['H_OBS'][:,0]<end_time_intervals_list[0])
                    if sum(mask)==0:
                        begin_time_intervals_list.pop(0)
                        end_time_intervals_list.pop(0)

                    else:
                        s=1

                #remove end intervals if no measurement is available within it; this is to avoid problems when interpolating
                s=0
                while s==0:
                    mask=(selected['H_OBS'][:,0]>=begin_time_intervals_list[-1])&(selected['H_OBS'][:,0]<end_time_intervals_list[-1])
                    if sum(mask)==0:
                        begin_time_intervals_list.pop(-1)
                        end_time_intervals_list.pop(-1)
                    else:
                        s=1
               
            elif user_selected_time_period=='MONTH':#for month, begin and end intervals are tricky because of the irregular length of month
                
                if begin_month==12:
                    tmin=date(begin_year+1, 1, 1).toordinal()#this is to make sure that the time interval begins at begin of next month
                else:   
                    tmin=date(begin_year, begin_month+1, 1).toordinal()
    
                if end_month==1:
                    tmax=date(end_year-1,12, 31).toordinal()#this is to make sure that the time interval ends at the end of last entire month
                
                elif end_month==3:
                    tmax=date(end_year,end_month-1, 28).toordinal()#this is to make sure that the time interval ends at the end of last entire month
                    
                elif end_month in [2,4,6,8,11]:
                    tmax=date(end_year,end_month-1, 31).toordinal()#this is to make sure that the time interval ends at the end of last entire month
                    
                else:
                    tmax=date(end_year,end_month-1, 30).toordinal()#this is to make sure that the time interval ends at the end of last entire month
                    
                #upadte begin_month and begin_year with the new tmin
                begin_datetime=datetime.fromordinal(tmin)
                begin_datetime_tuple=begin_datetime.timetuple()
                begin_year=begin_datetime_tuple.tm_year
                begin_month=begin_datetime_tuple.tm_mon
                
                begin_of_next_time_interval=tmin
                month=begin_month
                year=begin_year
                
                if begin_month==12:
                    end_of_next_time_interval=date(begin_year+1, 1, 1).toordinal()
                    month=1
                else:
                    end_of_next_time_interval=date(begin_year, begin_month+1, 1).toordinal()
                    month=month+1

                begin_time_intervals_list=[]
                end_time_intervals_list=[]
                
                while end_of_next_time_interval<=tmax:
                    
                    begin_time_intervals_list.append(begin_of_next_time_interval)
                    end_time_intervals_list.append(end_of_next_time_interval)
                    begin_of_next_time_interval=end_of_next_time_interval
                    
                    if month<12:
                        month=month+1
                        end_of_next_time_interval=date(year, month, 1).toordinal()
                    else:
                        month=1
                        year=year+1
                        end_of_next_time_interval=date(year, month, 1).toordinal()                

                
            elif user_selected_time_period=='YEAR':
      
                tmin=date(begin_year+1, 1, 1).toordinal()#this is to make sure that the time interval begins at begin of next month
                tmax=date(end_year,1, 1).toordinal()
                begin_of_next_time_interval=tmin
                
                
                #upadte begin_year with the new tmin
                begin_datetime=datetime.fromordinal(tmin)
                begin_datetime_tuple=begin_datetime.timetuple()
                begin_year=begin_datetime_tuple.tm_year
                end_of_next_time_interval=date(begin_year+1, 1, 1).toordinal()
                year=begin_year+1
      
                begin_time_intervals_list=[]
                end_time_intervals_list=[]
                
                while end_of_next_time_interval<=tmax:
                    begin_time_intervals_list.append(begin_of_next_time_interval)
                    end_time_intervals_list.append(end_of_next_time_interval)
                    begin_of_next_time_interval=end_of_next_time_interval
                    year=year+1
                    end_of_next_time_interval=date(year, 1, 1).toordinal()  

                

            #transforms lists in arrays
            array_of_begin_time_intervals=array(begin_time_intervals_list)    
            array_of_end_time_intervals=array(end_time_intervals_list)
            
            time_step=mean(array_of_end_time_intervals[:]-array_of_begin_time_intervals[:])     
            representative_times['H_OBS']=array_of_begin_time_intervals[:]+time_step/2
            begin_time_intervals['H_OBS']=array_of_begin_time_intervals
            end_time_intervals['H_OBS']=array_of_end_time_intervals


            
    #### SECTION 7: define time intervals for stress series by prolongation of the time intervals of groundwater head determined in las section
            

            #Determine time intervals voor stress time series, starting as basis the representative times of H_OB    
            tmin_hobs=begin_time_intervals['H_OBS'][0]
            begin_hobs_datetime=datetime.fromordinal(tmin_hobs)
            begin_hobs_datetime_tuple=begin_hobs_datetime.timetuple()
            begin_hobs_year=begin_hobs_datetime_tuple.tm_year
            begin_hobs_month=begin_hobs_datetime_tuple.tm_mon
            begin_hobs_day_of_the_week=begin_hobs_datetime_tuple.tm_wday#week day is zero for monday   

    
            for STRESS in list_of_explaining_stresses:
                tmin_stress=tmin_hobs-memory[STRESS]
                time_in_number=tmin_hobs
                month=begin_hobs_month
                year=begin_hobs_year
                
                if user_selected_time_period=='DAY':
                    begin_of_precedent_time_interval=time_in_number-1
                    end_of_precedent_time_interval=tmin_hobs#
                    
                    extra_begin_time_intervals_list=[]
                    extra_end_time_intervals_list=[]
    
                    while begin_of_precedent_time_interval>=tmin_stress:
                        extra_begin_time_intervals_list.insert(0,begin_of_precedent_time_interval)
                        extra_end_time_intervals_list.insert(0,end_of_precedent_time_interval)

                        end_of_precedent_time_interval=begin_of_precedent_time_interval
                        begin_of_precedent_time_interval=begin_of_precedent_time_interval-1  
                                  
            
                elif user_selected_time_period=='WEEK':
                    end_of_precedent_time_interval=tmin_hobs
                    begin_of_precedent_time_interval=time_in_number-7           
                    
                    extra_begin_time_intervals_list=[]
                    extra_end_time_intervals_list=[]
                    while begin_of_precedent_time_interval>=tmin_stress:
                        extra_begin_time_intervals_list.insert(0,begin_of_precedent_time_interval)
                        extra_end_time_intervals_list.insert(0,end_of_precedent_time_interval)

                        end_of_precedent_time_interval=begin_of_precedent_time_interval
                        begin_of_precedent_time_interval=begin_of_precedent_time_interval-7  
                            
                elif user_selected_time_period=='MONTH':
                    
                    end_of_precedent_time_interval=tmin_hobs
                    if month==1:
                        month=12
                        year=year-1
                    else:    
                        month=month-1
                    begin_of_precedent_time_interval=date(year, month, 1).toordinal()
                    
                    extra_begin_time_intervals_list=[]
                    extra_end_time_intervals_list=[]
                    
                    while begin_of_precedent_time_interval>=tmin_stress:
                        extra_begin_time_intervals_list.insert(0,begin_of_precedent_time_interval)
                        extra_end_time_intervals_list.insert(0,end_of_precedent_time_interval)
                        
                        if month>1:
                            month=month-1
                        else:
                            month=12
                            year=year-1
                        end_of_precedent_time_interval=begin_of_precedent_time_interval
