    reduced_percol_cumul=zeros((len(time),2))
    reduced_percol_cumul[:,0]=time
    
    winter_evap_cumul=zeros((len(time),2))#actual evap in winter
    winter_evap_cumul[:,0]=time     
    
    summer_evap_cumul=zeros((len(time),2))#actual evap in summer
    summer_evap_cumul[:,0]=time  
    
    summer_ref_evap_cumul=zeros((len(time),2))#ref evap in summer
    summer_ref_evap_cumul[:,0]=time     
          
    harmonic_component_evap_cumul=zeros((len(time),2))#part of evaporation associated with harmonic component
