    deviation_from_harmonic_component_evap=zeros((len(time),2))#part of evaporation associated with harmonic component
    deviation_from_harmonic_component_evap[:,0]=time     #$    
        
    #this has been added on 4-1-17: now, f can be time dependend but can remain of course constant    
    ft=zeros((len(time),2))#we call now f ft to indicate that it is now a time dependant variable
    ft[:,0]=time
    if flags['ROOT ZONE'] in [1,2,6,8]:
        ft[:,1]=f#constant f
        
        #seasons=zeros(len(time))
        #for j in range(0,len(time)):
        #    time_num=time[j]
