            #     print 'ft[i,1]',ft[i,1]
            #     print '(c3+c4)/c2',(c3+c4)/c2
            #     input()

    extra_output_dic['reduced_evap']=reduced_evap
    extra_output_dic['prec_cumul']=prec_cumul
    extra_output_dic['evap_cumul']=evap_cumul
    extra_output_dic['percol_cumul']=percol_cumul
    extra_output_dic['act_evap_cumul']=act_evap_cumul
    extra_output_dic['reduced_evap_cumul']=reduced_evap_cumul
    extra_output_dic['reduced_percol_cumul']=reduced_percol_cumul
    
    
    if flags['ROOT ZONE'] in [7]:           
        extra_output_dic['actual_summer_evaporation']=actual_summer_evaporation
        extra_output_dic['actual_winter_evaporation']=actual_winter_evaporation                               
