def MULTIPLY_STRESS_BY_SINUSOIDE(P,stress_serie,flags,process,mode='transform serie',pnumber=0,stress='PREC',logtransformed=[1,1],derivative='analytical',delp=0.01):
    #Step function for influence of river    P=array(P)
    from datetime import datetime
    from matplotlib.dates import date2num, num2date
    
    from datetime import datetime
    from matplotlib.dates import date2num, num2date
    
    new_stress_serie=zeros(shape(stress_serie))
    new_stress_serie[:,:]=stress_serie[:,:]
    
    P=array(P)
    logind=nonzero(logtransformed)[0]
    reference_datenum1=date2num(datetime(2000,3,1,0,0,0))#first reference date num is date number 1 Maart 1st 2000 at 00:00:00
    reference_datenum2=date2num(datetime(2010,3,1,0,0,0))#second reference date num is date number 1 Maart 2010 at 00:00:00
    period=(reference_datenum2-reference_datenum1)/10.0
    
    if len(logind)>0:
        P[logind]=exp(P)[logind]
    Min=float(P[0])#
    Max=float(P[1])
    newvalues=zeros(len(new_stress_serie))
    t=new_stress_serie[:,0]
    t_relative=abs(t-reference_datenum1)
    arguments=2*pi*t_relative/period
    seasonal_weights=sin(abs(arguments))

    if mode=='TRANSFORM':

        if process=='INTERCEPTION': #Min=minimum interception occuring in winter and Max is maxiumum interception (occuring in summer)
            intercepted_fraction=Min*ones(len(t))
            intercepted_fraction=intercepted_fraction+(Max-Min)*seasonal_weights
            newvalues[:]=(1-intercepted_fraction)*new_stress_serie[:,1]
            new_stress_serie[:,1]=newvalues[:]
            
        elif process=='TRANSPIRATION':
            transpirated_fraction=Min*ones(len(t))
            transpired_fraction=transpirated_fraction+(Max-Min)*seasonal_weights
            newvalues[:]=transpired_fraction*new_stress_serie[:,1]
            new_stress_serie[:,1]=newvalues[:]
            
        output=new_stress_serie
        
    elif mode=='partial derivative': #Attention: the seasonal fractions are discontinuously defined, so no derivative defined at season change
        if pnumber==0:  #partial differential with respect to Min

            if process=='INTERCEPTION': #Min=minimum interception occuring in winter and Max is maxiumum interception (occuring in summer)
                intercepted_fraction=ones(len(t))
                intercepted_fraction=intercepted_fraction+(Max-1)*seasonal_weights
                newvalues[:]=(1-intercepted_fraction)*new_stress_serie[:,1]
                new_stress_serie[:,1]=newvalues[:]
                
            elif process=='TRANSPIRATION':
                transpirated_fraction=ones(len(t))
                transpired_fraction=transpirated_fraction+(Max-1)*seasonal_weights
                newvalues[:]=transpired_fraction*new_stress_serie[:,1]
                new_stress_serie[:,1]=newvalues[:]


            output=new_stress_serie[:,1]
            if logtransformed[pnumber]==1:
                output=output*P[pnumber]            
        
        elif pnumber==1:  #partial differential with respect to Max       
        

            if process=='INTERCEPTION': #Min=minimum interception occuring in winter and Max is maxiumum interception (occuring in summer)
                intercepted_fraction=Min*ones(len(t))
                intercepted_fraction=intercepted_fraction+(1-Min)*ones(len(t))[trees_have_leaves]
                newvalues[:]=(1-intercepted_fraction)*new_stress_serie[:,1]
                new_stress_serie[:,1]=newvalues[:]
                
            elif process=='TRANSPIRATION':
                transpirated_fraction=Min*ones(len(t))
                transpired_fraction=transpirated_fraction+(1-Min)*ones(len(t))[trees_have_leaves]
                newvalues[:]=transpired_fraction*new_stress_serie[:,1]
                new_stress_serie[:,1]=newvalues[:]
            
            output=new_stress_serie[:,1]
            if logtransformed[pnumber]==1:
                output=output*P[pnumber]
                
    return output



def estimate_recharge(p,flags,logtrans_prec=[1,1,1,1],logtrans_evap=[1,1,1,1],indexes_prec=[0,1,2],indexes_evap=[0,1,2,3],prec_mean=0.8,evap_mean=0.6): #0008
    STRESS='PREC'
    functions_description_dic=generate_functions_specificities(STRESS,flags)
    BR_func=functions_description_dic['bloc response function name']
    logtrans_stress=logtrans_prec
    Pprec=[]
    for i in range(0,len(indexes_prec)):
        j=indexes_prec[i]
        Pprec.append(p[j])
    arguments_string=BR_func+'(Pprec,flags,x=0,mode='+"'M0'"+',stress='+"'"+STRESS+"'"+',logtransformed='+str(logtrans_stress)+')'
    M0_prec=eval(arguments_string)
    
    STRESS='EVAP'
    functions_description_dic=generate_functions_specificities(STRESS,flags)
    BR_func=functions_description_dic['bloc response function name']
    logtrans_stress=logtrans_evap
    Pevap=[]
    for i in range(0,len(indexes_evap)):
        j=indexes_evap[i]
        Pevap.append(p[j])    
    arguments_string=BR_func+'(Pevap,flags,x=0,mode='+"'M0'"+',stress='+"'"+STRESS+"'"+',logtransformed='+str(logtrans_stress)+')'
    M0_evap=eval(arguments_string)    
    
    f=M0_evap/M0_prec
    groundwater_recharge=prec_mean-f*evap_mean
    
    return groundwater_recharge




def part_response(func,P,serie,Nint,flags,time_step,x=0,mode='BR',pnumber=0,stress='PREC',logtransformed=[1,1,1,1],derivative='analytical',delp=0.01):                      #response serie as level difference from mean using a block or impulse response function
    import numpy as np
    x=x
    time_step=time_step
    Nint=Nint
    mode=mode
    pnumber=pnumber
    stress=stress
    logtransformed=logtransformed
    derivative=derivative
    delp=delp
    W=func(P,flags,x=x,time_step=time_step,Nint=Nint,mode=mode,pnumber=pnumber,stress=stress,logtransformed=logtransformed,derivative=derivative,delp=delp)                                        #weights vector for the convolution
    M0=func(P,flags,x=x,time_step=time_step,Nint=Nint,mode='M0',pnumber=pnumber,stress=stress,logtransformed=logtransformed,derivative=derivative,delp=delp)
    conv=np.convolve(W,serie,'valid')
    return conv

def part_response_continuous(func,P,flags,stress_serie,h_serie,memory,x=0,mode='BR',pnumber=0,stress='PREC',logtransformed=[1,1,1,1],derivative='analytical',delp=0.01):                      #response serie as level difference from mean using a block or impulse response function
    #USE OF THIS FUNCTION ONLY IF STRESS SERIES ARE INTENSITIE, SO QUANTITIES DIVIDED BY TIME
    import numpy as np
    x=x
    mode=mode
    pnumber=pnumber
    stress=stress
    logtransformed=logtransformed
    derivative=derivative
    delp=delp
    tobs=h_serie[:,0]
    partial_response=999*ones(len(h_serie))
    stress_times=stress_serie[:,0]#time of stress observations
    stress_values=stress_serie[:,1]#observed stress values
    
    for i in range(0,len(tobs)):
        t=tobs[i]
        time2stressbegin=t-stress_times#vector difference t minus begin time of observed stress
        mask=(time2stressbegin>0) & (time2stressbegin<=memory)
        stress_length=stress_times[1:]-stress_times[::-1]#vector time steps (not available for last element of stess array)  
        indexes=arange(0,len(stress_serie))#array of indexes of all elements in serie
        indexes=indexes[mask]#indexes of the entries in the stress vector which will contribute to the convolution
        indexes_BR=indexes[::-1]#indexes of stresses the effect of which will be accounted by a blok response
        index_SR=indexes[-1]#the stress starting at the last stress time before the observed head time is not finished, so it is accounted for by a step function
        weights=zeros(len(stress_serie))
        weights[indexes_BR]=func(P,flags,time2stressbegin[indexes_BR],stress_length[indexes_BR],x=0,step_response=False,mode=mode,pnumber=pnumber,stress=stress,logtransformed=logtransformed,derivative=derivative,delp=delp)
        weights[index_SR]=func(P,flags,time2stressbegin[index_SR],time2stressbegin[index_SR],x=0,step_response=True,mode=mode,pnumber=pnumber,stress=stress,logtransformed=logtransformed,derivative=derivative,delp=delp)
        convolution=sum(weights*stress_values)# sum(stress(tau)*BR(t-tau))
        partial_response[i]=convolution

    return partial_response


def eval_trend_or_step(P,time,logtransformed=array([1,1,1,1,1],dtype=bool),TREND_OR_STEP='TREND'):

    logind=nonzero(logtransformed)[0]
    P=array(P)
    
    P[logind]=exp(P)[logind]

    indexes_trend_or_step=arange(0,len(time))
    trend_or_step=zeros((len(time),2))
    trend_or_step[:,0]=time[:]
        
    if TREND_OR_STEP=='TREND':
        if flags['TREND']==1:
            H=100-P[0]#because the height at end of the trend is given relative to 100
            for i in range(0,len(time)):
                trend_or_step[i,1]=H*i/len(time)
                
        elif flags['TREND']==2:
            RT=P[0]
            H=100-P[1]
            index_begin=int(RT*len(time))
            for i in range(index_begin,len(time)):
                trend_or_step[i,1]=H*(i-index_begin)/(len(time)-index_begin )
                
        elif flags['TREND']==3:
            
            def edelman(diffusivity,x,t):
                u=x*sqrt(1.0/(4.0*diffusivity*t))
                return scipy.special.erfc(u)
     
            RT=P[0]
            Edelman_step=100-P[1]
            x=P[2]

            diffusivity=P[3]

            
            index_begin=int(RT*len(time))
            for i in range(index_begin,len(time)):
                t=(i-index_begin)*time_step
                delta_h=Edelman_step*edelman(diffusivity,x,t)
                trend_or_step[i,1]=delta_h                
                            
            #fig=figure()
            ##from os import getcwd
            ##curdir=os.getcwd()
            #ax = fig.add_subplot(111)
            ##ax.set_title('line 5355 crop factor')
            #ax.plot_date(trend_or_step[:,0],trend_or_step[:,1],'b',markersize=10)
            #leg = ax.legend((['trend or step']),loc='upper left',shadow=False)
            #ax.set_xlabel('date')
            #ax.grid(False)
            #ax.fmt_xdata = DateFormatter('%Y-%m-%d')                        # %H:%M:%S
            #fig.autofmt_xdate()
            ##savefig(curdir+'\\crop_factor', dpi=None, facecolor='w', edgecolor='w',orientation='portrait', papertype=None, format=None,transparent=False, bbox_inches=None, pad_inches=0.1)
            #show()
            #input()
    
    
    elif TREND_OR_STEP=='STEP':
        RT=P[0]
        H=100-P[1]
        select=indexes_trend_or_step[:]>RT*len(time)
        trend_or_step[select]=trend_or_step[select]+H
        
    #if flags['test']==2:
    #
    #    fig=figure()
    #    #from os import getcwd
    #    #curdir=os.getcwd()
    #    ax = fig.add_subplot(111)
    #    #ax.set_title('line 5355 crop factor')
    #    ax.plot_date(trend_or_step[:,0],trend_or_step[:,1],'b',markersize=10)
    #    leg = ax.legend((['trend or step']),loc='upper left',shadow=False)
    #    ax.set_xlabel('date')
    #    ax.grid(False)
    #    ax.fmt_xdata = DateFormatter('%Y-%m-%d')                        # %H:%M:%S
    #    fig.autofmt_xdate()
    #    #savefig(curdir+'\\crop_factor', dpi=None, facecolor='w', edgecolor='w',orientation='portrait', papertype=None, format=None,transparent=False, bbox_inches=None, pad_inches=0.1)
    #    show()
    #    input()
    #
    #    

    return trend_or_step


def case_selection(STRESS,flags):#0001$

    if STRESS=='PREC':
        if flags['PREC']in [6,7]:
            case=1
