def response(P,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list,derivative='analytical',delp=0.01):#$
    #response calculates the heads and the derivatives of the head and moments with respect to parameters
    #P_ind is a dictionary of list of indexes relating the position of a parameter localy in the function in which it is used to its position in the global parameter vector
    #flags['PREC'],flags['EVAP'],flags['RIV'],flags['WELL'],flags['NOISE'] are flags determining which response function is used for each stress
    #time_step is the length of a time step in days
    #Nint means 'Number of intervales' and is the number of time steps used to calculate the response of a stress
    #select_data and select_parameters have only effect on the calculation of the jacobian
    #logtransform is a boolean list determing if a parameter is logtransformed (value=1) or not (value=0)
    #stress_list is the list of stresses used to simulate the time serie of groundwater fluctuations
    
    import numpy as np               #P contains all possible parameters in the following order: A,a,n of Prec, Log10_f of EVAP, RIV
    from scipy import interpolate
    from datetime import datetime
    from scipy.stats.mstats import gmean
    
    P_list=split_P(P,P_ind,flags)
    P_dic={}
    P_dic['PREC']=P_list[0]
    P_dic['EVAP']=P_list[1]
    if flags['ROOT ZONE'] in [1,2,3,4,5,6,7,8,100,101,102,103,200]:
        for e in P_dic['EVAP']:
            P_dic['EVAP'][e][0]=P_dic['EVAP'][e][0]/1000#eliminate evap if root zone is used #tag012
        
    P_dic['RIV']=P_list[2]
    P_dic['WELL']=P_list[3]
    P_dic['INTERCEPTION']=P_list[4]
    P_dic['TRANSPIRATION']=P_list[5]
    P_dic['SOIL EVAP']=P_list[6]
    P_dic['NOISE']=P_list[7]
    P_dic['db']=P_list[8]
    P_dic['ROOT ZONE']=P_list[9]
    P_dic['TREND']=P_list[10]
    P_dic['STEP']=P_list[11]
    

    logtransformed_list=split_P(logtransform,P_ind,flags)
    logtrans_dic={}
    logtrans_dic['PREC']=logtransformed_list[0]
    logtrans_dic['EVAP']=logtransformed_list[1]
    logtrans_dic['RIV']=logtransformed_list[2]
    logtrans_dic['WELL']=logtransformed_list[3]
    logtrans_dic['INTERCEPTION']=logtransformed_list[4]
    logtrans_dic['TRANSPIRATION']=logtransformed_list[5]
    logtrans_dic['SOIL EVAP']=logtransformed_list[6]    
    logtrans_dic['NOISE']=logtransformed_list[7]
    logtrans_dic['db']=logtransformed_list[8]
    logtrans_dic['ROOT ZONE']=logtransformed_list[9]
    logtrans_dic['TREND']=logtransformed_list[10]
    logtrans_dic['STEP']=logtransformed_list[11]
    
    derivative=derivative
    delp=delp
    
    lind=select_data#indexes of selected colomns
    cind=select_parameters#indexes of selected lines
    
    h_obs_interp=data['H_OBS']['interpolated']
    h_obs=data['H_OBS']['observed selected']
    targets=data['H_OBS']['targets']
    
    if flags['TIME DERIVATIVE']==1:
        h_obs_interp=data['H_OBS']['time derivative']
        h_obs=h_obs_interp

    if flags['SMOOTH']==1:
        h_obs_smoothed=data['H_OBS']['smoothed']
    
    
    X=float(data['H_OBS']['metadata']['X'])
    Y=float(data['H_OBS']['metadata']['Y'])
    if 'extra code 1' in data['H_OBS']['metadata']:
        flags['LAYER']=int(data['H_OBS']['metadata']['extra code 1'])
    else:
        flags['LAYER']=0

    if flags['SMOOTH']==0:
        if flags['INTERPOLATE']==0:
            time=h_obs[:,0]#time for which convolution is evaluated
        else:
            time=h_obs_interp[:,0]#time for which convolution is evaluated
            
    elif flags['SMOOTH']==1:
        time=h_obs_smoothed[:,0]
        
    if flags['SIMULATE']==0 or flags['TEST PARAMETERS SENSITIVITY']==1:    
        J=zeros((len(time),len(P)))#declare the analytical jacobian of the groundwater head function with respect to model parameters
        if 'db' in P_ind:#if yes, then drainage base is a parameter
            ind_db=P_ind['db']['db'][0]  
            if ind_db in select_parameters:#if yes, then db is a parametr to optimize 
                
                J[:,ind_db]=ones(len(time))#fill in the colomn corresponding to db; if db is not a parameter, this colomn is written over
    else:
        J=[]
    
    resp={}
    grad={}#this is in case a flux is estimated instead of head, the gradient of the head is calculated
    mean_resp=0
    mean_grad=0
    gain=0#gain is the structural level, that is the average head if all stresses are constant
    
    for STRESS in stress_list:
        
        resp[STRESS]={}
        if flags['SIMULATE']==1:
            if flags['GRADIENT']==1:
                grad[STRESS]={}
        
        if flags['INTERPOLATE']==1:
            if STRESS=='PREC':#this are factors that can be manually adjusted to correct a time serie (usful for EVAP if no f factor is available in the model)
                adjust=1.0/time_step#correct the fact that prec needs to be in m/dag while quantities are given in m per time step
            elif STRESS=='EVAP':
                adjust=1.0/time_step#correct the fact that evap needs to be in m/dag while quantities are given in m per time step
            elif STRESS=='RIV':
                adjust=1.0
            elif STRESS=='WELL':
                adjust=1.0
                #if flags['WELL'] in [0,2,3]: #in which case it is incomplete gamma or exp response function
                #    adjust=1.0#/time_step
                #else:#in which case response functions are well functions so time series must be in m3/day
                #    adjust=1.0
        
        
        if STRESS in ['EVAP','WELL']:
            sign=-1
        else:
            sign=1
        x=0 #default value when no distance is needed to calculate the response
        
        if 'distance to river' in data['H_OBS']['metadata']:
            x=float(data['H_OBS']['metadata']['distance to river'])
                  
        for e in data[STRESS]:
            
            if STRESS=='WELL':
                Xw=float(data['WELL'][e]['metadata']['X'])#data['WELL'][e] is a 2 elements list, the first being the well observed time serie, the second being the dictionary of metadata
                Yw=float(data['WELL'][e]['metadata']['Y'])
                x=sqrt((X-Xw)**2+(Y-Yw)**2)
                
            ind=P_ind[STRESS][e] 
            Pstress=P_dic[STRESS][e]
