                                        stress_part_min=eval(transform_func+'(P_transform_stress_min,stress,flags,PROCESS,mode=mode,pnumber=0,stress=STRESS,logtransformed=logtransformed_transform_stress,derivative=derivative,delp=0.01)')  
                                        stress_preprocess[PROCESS][STRESS]['STRESS COMPONENT PLUS']=stress_part_plus#
