                                    part_resp_min=sign*part_resp_from_double_IR(Pmin,stress,time,flags,arg_dic,STRESS=STRESS)
       
                                    num=part_resp_plus-part_resp_min
                                    
                                    if logtransform[j]==1:                        
                                        num=num*P[j]

                                    denom=Pplus[i]-Pmin[i]
                                    J_kolom_vector=num/denom
                                    J[:,j]=J[:,j]+J_kolom_vector[:] #0001$

