    def ci_backtransformation_from_logtransform(mean,stdev,sample_size=1000,alfa=0.05):
        from numpy.random import normal,multivariate_normal,uniform,triangular#import more than necessary, just in case we want to try something else
        #X=exp(mean+stdev*Z) with Z=N(0,1) and X is the natural paramater, thus back transformed from log
        deviations=normal(0,1, size=sample_size)
        deviations=stdev*normal(0,1, size=sample_size)
        exponents=mean+deviations
        samples=exp(exponents)
        b=argsort(samples[:])#indexes of first colomn entries sorted in increasing order
        sort=samples[b]#M0 sorted in increasing order
        #ind_low=int(alfa/2*sample_size)
        ind_low=int(alfa*sample_size)
        low_bound=sort[ind_low]
        #ind_high=int((1-alfa/2)*sample_size)
        ind_high=int((1-alfa)*sample_size)
        high_bound=sort[ind_high]
        ci=[low_bound,high_bound]
        #stdev_montecarlo=sqrt(var(samples[ind_low:ind_high]))
        stdev_montecarlo=sqrt(var(samples))
        return ci,stdev_montecarlo,samples
        
        
    
    def parameters_distributions_mc_old(Psimul,location,scale,select_parameters,rangeMin,rangeMax,sample_size=1000):# creates a list of parameters realisations which can be used for stochastic evaluation of functions of the parameters  
        from numpy.random import normal,multivariate_normal,uniform,triangular#import more than necessary, just in case we want to try something else
        #estimate uncertainty of functions of parameters
        sample_size=sample_size
        rangeMin_array=array(rangeMin)
        rangeMax_array=array(rangeMax)

        if len(location)>1:#multivariate
            sample_parameters=multivariate_normal(location, scale, size=sample_size)#location and scale must include all parameters used in the time series analysis, also the non optimized ones and the ones corresponding to stresses not included in the structural level
            for j in range(0,len(location)):
                #mask=(sample_parameters[:,j]<rangeMin_array[select_parameters][j]) | (sample_parameters[:,j]>rangeMax_array[select_parameters][j])
                #uniform_sampled=uniform(low=rangeMin_array[select_parameters][j],high=rangeMax_array[select_parameters][j],size=sample_size)
                mask=(sample_parameters[:,j]<rangeMin_array[j]) | (sample_parameters[:,j]>rangeMax_array[j])
                uniform_sampled=uniform(low=rangeMin_array[j],high=rangeMax_array[j],size=sample_size)
                sample_parameters[mask,j]=uniform_sampled[mask]

        else:#univariate
            location=location[0]
            scale=sqrt(scale)#because in the univariate case, the scale is the standard deviation, not the variance
            sample_parameters=normal(location, scale, size=sample_size)
        samples_parameters_complete=zeros((len(sample_parameters),len(Psimul)))
        samples_parameters_complete[:,:]=Psimul#use of Python broadcasting
        samples_parameters_complete[:,select_parameters]=sample_parameters[:,:]#use of Python broadcasting
        return samples_parameters_complete
    
    
    
