def jacobian_finite_difference(P,data,stress_preprocess,time_step,flags,Nint,select_data,select_parameters,logtransform,stress_list,delp=0.1):#jacobian for hermonic componnt

    P0pas=flags['P0pas']##added 9-12-17, quick & dirty way to smuggle P0pas into functions which do not have P0pas as arguments 

    if flags['FIT HARMONIC COMPONENT']==1:
        nb=14 #nb is the number of the output element of response
    elif flags['FIT HARMONIC COMPONENT']==2:
        nb=15    #nb is the number of the output element of response

        
    # condition_to_use_jacobian_finite_difference=0#0001
    # if flags['INCLUDE GAIN IN OPTIMISATION']==1:
    #     condition_to_use_jacobian_finite_difference=1
    # if flags['FIT HARMONIC COMPONENT']==3:
    #     condition_to_use_jacobian_finite_difference=1   
    # if flags['USE JACOBIAN AS MODEL FINITE DIFFERENCE']==1:  
    #     condition_to_use_jacobian_finite_difference=1
        
    #if condition_to_use_jacobian_finite_difference==1:#0001$:
    if flags['NOISE']==1: #0001
        nb=4
    else:
        nb=1    #nb is the number of the output element of response       #0001$ 
        
    nl=len(data['H_OBS']['interpolated'])#in first instance, number of lines matrix equals number of interpolated obervations
    nc=len(P)
    lind=select_data#indexes of selected colomns
    cind=select_parameters#indexes of selected lines
    J=empty((nl,nc))

    P=array(P)#from list type to array type in order to perform the additionb P+dP
    
    ###########################################################
    dp=abs(P)*delp                               #del p for non log transformed parameters
    dp[flatnonzero(logtransform)]=log(1+delp)    #replace dp for log transformed parameters by exp(P)*delpmin
    #indexes=where(dp<delpmin)[0]                      #returns indexes of vector dp where value is smaller than delpmin
    #dp[indexes]=delpmin#replaces values smaller than delpmin by delpmin
    #########################################################
    #dp=delpmin*ones((len(P)))
    dp=diag(dp)#diagonal matrix of perturbations
    P=P+zeros((len(P),len(P)))#attention, this is python broadcasting in action!result is a square matrix of length P, with each line=P
    Pp=P+dp
    Pm=P-dp#Pp for 'P plus' and Pm for 'P min'

    
    flags['SIMULATE']=1#this is to avoid calculating all derivatives in response 
    for j in range(0,nc):##$
        Pplus=Pp[j,:]
        Pmin=Pm[j,:]
        if flags['FIT HARMONIC COMPONENT']==3:    #0001
            Pplus,P0pas=update_P_given_harmonic_components(Pplus,Pnames,P0pas,P0pas_index,flags,logtransform)    
            Pmin,P0pas=update_P_given_harmonic_components(Pmin,Pnames,P0pas,P0pas_index,flags,logtransform)          
        response_plus=response(Pplus,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list)
        response_min=response(Pmin,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list)
        if nb in [14,15]:
            J[:,j]=(response_plus[nb][:,1]-response_min[nb][:,1])/(Pp[j,j]-Pm[j,j])
        else: 
            J[:,j]=(response_plus[nb][:]-response_min[nb][:])/(Pp[j,j]-Pm[j,j])
      
    flags['SIMULATE']=0
    J=J.take(lind,axis=0)#select lines
    J=J.take(cind,axis=1)#select colomns
    #J[J<1e-14]=0
    return J
    



def jacfunc(P,func,time,logtransform=array([],dtype=bool),delp=0.05):#this is a more simpel and general jacobian applicable for a function func and parameters vectors p
    nl=len(time)#in first instance, number of lines matrix equals number of interpolated obervations
    nc=len(P)
    J=empty((nl,nc))
    P=array(P)#from list type to array type in order to perform the additionb P+dP
    dp=abs(P)*delp#del p for non log transformed parameters
    dp[logtransform]=log(delp+1)#replace dp for log transformed parameters 
    dp=diag(dp)#diagonal matrix of perturbations
    P=P+zeros((len(P),len(P)))#attention, this is python broadcasting in action!result is a square matrix of length P, with each line=P
    Pp=P+dp
    Pm=P-dp#Pp for 'P plus' and Pm for 'P min'
    for j in range(0,nc):
        J[:,j]=(func(Pp[j,:],time)-func(Pm[j,:],time))/(Pp[j,j]-Pm[j,j])
    return J



def LM_jacan(P0,data,time_step,P_ind,Nint,flags,select_data,select_parameters,logtransform,stress_list,eps1=1e-10,eps2=1e-10,eps3=1e-10,maxiter=30):#LM with analytical jacobian

    from numpy import var,std
    from numpy.linalg import solve,inv,det,LinAlgError#,dot,diag, transpose, norm
    from scipy.linalg import diagsvd

    
