def basenames(fseries_files):#make a dictionary of basenames from fseries files
    basenames={}
    for s in fseries_files:
        basenames[s]=[]
        for e in fseries_files[s]:
            a=e.split('\\')#from the whole file name, we extract the base name of the well or other stress
            a=a[len(a)-1].split('.')
            basenames[s].append(a[0])
    return basenames


