def retrieve_P(Pact,Pact_index,Ppas,Ppas_index):
    P=[]
    Plength=len(Pact)+len(Ppas)
    for i in range(0,Plength):
        if i in Pact_index:
            P.append(Pact[where(array(Pact_index)==i)[0][0]])#where(Pact_index==i)[0][0]returns the index in Pact of the parameter corresponding to index i in the parameter vector P
        else:
            P.append(Ppas[where(array(Ppas_index)==i)[0][0]])
    return P


def autocor(serie,time_step):
    m=mean(serie)
    v=var(serie)
    lag_max=len(serie)/2#returns as integer the number of time lags which will be tested
    N=len(serie)
    R=999*ones((lag_max,2))
    for n in range(0,lag_max):
        lag=n+1
        R[n,0]=lag*time_step
        autoc=0
        for k in range(0,N-lag):
            autoc=autoc+(serie[k+lag]-m)*(serie[k]-m)
        R[n,1]=autoc/((N-lag)*v)
    return R

