    Istress_default={'PREC':0.0015,'EVAP':0.0007,'RIV':1,'WELL':1200}
    Istress_dic={}
    for key in data:
        if key in ['PREC','EVAP','WELL']:
            stress=key
            Istress_dic[stress]={}
            for e in data[stress]:
                if a=='y':
                    Istress_dic[stress]['data source']='user input'
