        output['simulated flux by gradient method']=simulated_flux_method1
        output['simulated specific seepage by gradient method']=seepage
        
        #if model_name=='P1':
        #    e=data['RIV'].keys()[0]#if there was more than one river, take the first one as default choice
        #    riv=data['RIV'][e]['interpolated river stage']
        #    phi2=h_obs_interp
