        #    print '10431 average difference head P1 - river stage :',mean(head_P1_minus_river_stage[:,1])
        #    
        #    fig=figure()
        #    ax = fig.add_subplot(111)
        #    ax.plot_date(h_obs_interp[:,0],h_obs_interp[:,1],'r')#plot simulated time serie
        #    ax.plot_date(riv[:,0],riv[:,1],'k')#plot simulated time serie
        #    ax.set_title('Comparison river stage and groundwater stage'+model_name)
