    err=y_all-simulation_det_all          
    err=dot(diag(weights_all),err)

    if flags['NOISE']==1:
        err_stoch=y_all-simulation_stoch_all         #innovations
        err_stoch=multiply(err_stoch,SSWI_all) #weighted innovations
