def regular_sampling_not_log(rangeMin,rangeMax,npp,np):#npp is number of samples per parameters, minimum 2
    #returns a list of non log transformed parameters values, regularly sampled
    from numpy.random import uniform
    
    Nsamples=npp**np
    #define for each parameters the values which will be tested
    list_of_list_of_parameters_values=[]#parameters segments list
    for p in range(0,np):
        Pmin=rangeMin[p]
        Pmax=rangeMax[p]
        list_of_parameters_values=[Pmin]
        if npp>2:
            parameter_interval=float((Pmax-Pmin)/np)
        Psample=Pmin
        for i in range(0,npp-2):
            Psample=Psample+parameter_interval
            list_of_parameters_values.append(Psample)
        list_of_parameters_values.append(Pmax)
        list_of_list_of_parameters_values.append(list_of_parameters_values)        
    
    #matrix of parameters samples
    parameters_samples=zeros((Nsamples,np))#matrix of latin hypercube samples
    for j in range(0,np):
        list_of_parameters_values=list_of_list_of_parameters_values[j]
        i1=0
        i2=0
        step=npp**(np-j-1)
        while i2<Nsamples:
            for i in range(0,npp):
                i2=i1+step
                parameters_samples[i1:i2,j]=list_of_parameters_values[i]
                i1=i2
            
    F=open('parameters_regular_sampling.csv','w') #open output file for sorted complexes
    header='Total number of parameters samples: '+str(Nsamples)+',Number of parameters samples per parameter: '+str(npp)
    F.write(header+'\n')
    for i in range(0,Nsamples):
        record=str('%10.4f' %parameters_samples[i,0])
        for j in range(1,len(parameters_samples[i,:])):
            record=record+','+str('%10.4f' %parameters_samples[i,j])
        F.write(record+'\n')
    F.close()

    return parameters_samples



def computedensity_mcmc(P,mcmc_arguments): #compute probability density for given parameter point P for mcmc
    
    model_arguments=mcmc_arguments['model arguments']
    func=mcmc_arguments['model function name']
    density_type=mcmc_arguments['density type']#direct probability, error minimization or likelihood=mcmc_arguments['density_type']
    data=mcmc_arguments['data']
    stress_preprocess=mcmc_arguments['stress preprocess']
    time_step=mcmc_arguments['time_step']
    P_ind=mcmc_arguments['P_ind']
    flags=mcmc_arguments['flags']
    select_data=mcmc_arguments['select_data']
    select_parameters=mcmc_arguments['select_parameters']
    logtransform=mcmc_arguments['logtransform']
    stress_list=mcmc_arguments['stress_list']
    derivative=mcmc_arguments['derivative']='analytical'
    delp=mcmc_arguments['delp']
    flags=mcmc_arguments['flags']
    kurt=mcmc_arguments['kurt']
    Nint=mcmc_arguments['Nint']
        
    if density_type=='direct probability':
        density=eval(func+'(P'+','+model_arguments+')')
        
    elif density_type=='likelihood':
        Pmodel=P[:-2]
        Pdistribution=P[-2:]
        
        #equation [5] of scemua manual,which is almost never usable because we do not know stdev_residuals before optimizing!
        A1 = gamma(3.0*(1.0+kurt)/2.0) 
        A2 = gamma((1.0+kurt)/2.0)
        Cb = (A1/A2)**(1.0/(1.0+kurt))
        Wb = sqrt(A1)/((1.0+kurt)*(A2**(1.5)))
        #stdev_residuals=scemua_arguments['stdev_residuals']
        stdev_residuals=Pdistribution[0]
        kurt=Pdistribution[1]
        #Yobs=scemua_arguments['targets']
        #Ysim=eval(func+'(P'+','+model_arguments+')')
        err=residuals(Pmodel,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,stress_list)
        if flags['NOISE']==0:
            errors=err[0][:,1]
        elif flags['NOISE']==1:
            SSWI_weights=err[2]
            errors=multiply(err[1][:,1],SSWI_weights)
        N=len(errors)
            
        # taking logarithm of Equation 5 from the manual
        density = N*log(Wb/stdev_residuals) - Cb*(sum((abs(errors/stdev_residuals))**(2/(1+kurt))))
        
    #elif density_type=='error minimization':#using logarithm of equation [7] of scemua manual, which is proportional to equation [8] of scemua manual
    #    #Yobs=scemua_arguments['targets']
    #    #Ysim=eval(func+'(P'+','+model_arguments+')')
    #    err=residuals(P,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,Istress_dic,stress_list)
    #    
    #    if flags['NOISE']==0:
    #        errors=err[0][:,1]
    #    elif flags['NOISE']==1:
    #        SSWI_weights=err[2]
    #        errors=multiply(err[1][:,1],SSWI_weights)
    #    N=len(errors)
    #      
    #    # Taking logarithm of Equation 5 from the manual
    #    density = -sum(pow(abs(errors),(2/(1+kurt))))
    
   
    elif density_type=='error minimization':#using logarithm of equation [7] of scemua manual, which is proportional to equation [8] of scemua manual
        
        #Ysim=eval(func+'(P'+','+model_arguments+')')
        y=data['H_OBS']['targets'][:,1]#targets
        mask_y=data['H_OBS']['mask']
        r=response(P,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list,derivative=derivative,delp=delp)
        if flags['NOISE']==0:
            simulation=r[1][mask_y]
            err=y-simulation
        elif flags['NOISE']==1:
            simulation=r[4][mask_y]
            err=y-simulation
            res=residuals(P,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,stress_list)
            SSWI_weights=res[2]
            err=multiply(err,SSWI_weights) #weighted innovations
        
        SStot=sum(pow(data['H_OBS']['targets'][:,1]-mean(data['H_OBS']['targets'][:,1]),2))
        SSreg=sum(pow(err,2))
        expvar=100*(1-SSreg/SStot)
        density=expvar
    
    return density


def compute_objective_functions(P,monte_carlo_multi_objective_dic):
    
    maximum_model_evaluations_number=5000
    #
    P0=array(monte_carlo_multi_objective_dic['P0'])
    Popt_GaussNewton=array(monte_carlo_multi_objective_dic['Popt Gauss Newton'])
    rangeMin=monte_carlo_multi_objective_dic['rangeMin']
    rangeMax=monte_carlo_multi_objective_dic['rangeMax']
    data=monte_carlo_multi_objective_dic['data']
    time_step=monte_carlo_multi_objective_dic['time_step']
    P_ind=monte_carlo_multi_objective_dic['P_ind']
    select_data=monte_carlo_multi_objective_dic['select_data']
    select_parameters=monte_carlo_multi_objective_dic['select_parameters']
    logtransform=monte_carlo_multi_objective_dic['logtransform']
    flags=monte_carlo_multi_objective_dic['flags']
    Pnames_all=monte_carlo_multi_objective_dic['Pnames']#all parameter names
    #model_name=monte_carlo_multi_objective_dic['model name']
    #number_of_samples=monte_carlo_multi_objective_dic['number of samples']
    model_arguments=monte_carlo_multi_objective_dic['model arguments']
    stress_preprocess=monte_carlo_multi_objective_dic['stress preprocess']
    model_function_name=monte_carlo_multi_objective_dic['model function name']
    derivative=monte_carlo_multi_objective_dic['derivative']
    delp=monte_carlo_multi_objective_dic['delp']
    DATA=monte_carlo_multi_objective_dic['DATA']
    monte_carlo_multi_objective_dic['number of samples']=5000      
   
    list_of_objective_func=monte_carlo_multi_objective_dic['list of objective func']

    scores_dic={}
    
    for objective in list_of_objective_func:
        r=response(P,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list,derivative=derivative,delp=delp)

        if objective=='NS': #Nash Sutcliffe
            y=data['H_OBS']['targets'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask']
            simulation=r[1][mask_y]
            err=y-simulation     
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar
            scores_dic['NS']=density
        
        elif objective=='NS_peaks':   
            y=data['H_OBS']['targets peaks'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask peaks']            
            simulation=r[1][mask_y]
            err=y-simulation     
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar
            scores_dic['NS_peaks']=density            

        elif objective=='NS_log':
            y=log(data['H_OBS']['targets'][:,1])#all data must be positive!
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask']
            simulation=log(r[1][mask_y])
            err=y-simulation
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar         
            scores_dic['NS_log']=density  
            
        elif objective=='NS_deriv':#from here on, option noise is not supported anymore
            y=data['H_OBS']['targets derivative'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask']
            simulation=r[1][mask_y]
            err=y-simulation
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar         
            scores_dic['NS_deriv']=density           
 
        elif objective=='NS_deriv_peaks':
            y=data['H_OBS']['targets derivative peaks'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask derivative peaks']
            simulation=r[1][mask_y]
            err=y-simulation
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar             
            scores_dic['NS_deriv_peaks']=density
            
        elif objective=='NS_diff':#from here on, option noise is not supported anymore
            y=data['H_OBS']['targets diff'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask']
            simulation=r[1][mask_y]
            err=y-simulation
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar         
            scores_dic['NS_diff']=density           
 
        elif objective=='NS_diff_peaks':
            y=data['H_OBS']['targets diff peaks'][:,1]#targets
            y_mean=mean(y)
            mask_y=data['H_OBS']['mask diff peaks']
            simulation=r[1][mask_y]
            err=y-simulation
            SSreg=sum(pow(err,2))
            SStot=sum(pow(y-y_mean,2))
            expvar=100*(1-SSreg/SStot)
            density=expvar             
            scores_dic['NS_diff_peaks']=density  

    return scores_dic



