def eval_correlation_LHS(models,DATA,fseries_files,P_ind,flags,stress_list,Pnames_optim,delp=0.05):  

    number_of_samples=250000#0005$
    
    for m in models:

        time=models[m]['h simulated'][:,0]
        Popt=models[m]['Popt']
        Pnames=models[m]['Pnames']
        data=models[m]['data']
        time_step=models[m]['time_step']
        P_ind=models[m]['P_ind']
        flags=models[m]['flags']
        select_data=models[m]['select_data']
        select_parameters=models[m]['select_parameters']
        logtransform=models[m]['logtransform']
        stress_list=models[m]['stress_list']
        flags=models[m]['flags']
        Nint=models[m]['Nint'] 
        
        logtransform_select=logtransform[select_parameters]
        y=data['H_OBS']['targets'][:,1]#targets
        weights=data['H_OBS']['targets weights'][:,1]
        indlt=flatnonzero(logtransform_select)#indexes of log transformed parameters
        mask_y=data['H_OBS']['mask']
        
        derivative='analytical'
        derivative='numerical'           

        P=array(Popt[select_parameters])#from list type to array type in order to perform the additionb P+dP
        #delp2=0.1  
        delp2=delp
        dp=abs(P)*delp2#del p for non log transformed parameters
        dp[logtransform_select]=log(delp2+1)#replace dp for log transformed parameters 
        dp=diag(dp)#diagonal matrix of perturbations
        P=P+zeros((len(P),len(P)))#attention, this is python broadcasting in action!result is a square matrix of length P, with each line=P
        Pp=P+dp
        Pm=P-dp#Pp for 'P plus' and Pm for 'P min'#
        # delp=0.05
        
        rangeMin=diag(Pm)
        rangeMax=diag(Pp)
          
        samples_not_log=latinhypercubesampling(rangeMin,rangeMax,number_of_samples,logtransform=logtransform_select)#returns not logtransformed values!

        samples_log=empty(shape(samples_not_log))
        samples_log[:,:]=samples_not_log[:,:]
        NL=len(samples_log)+1#+1 because we add the optimal parameter vector
        NP=len(P)

        NC=NP+1#+1 because we add a colomn for score
        samples_matrix_not_log=empty((NL,NC))
        samples_matrix_log=empty((NL,NC))
                   

        #fill in sample matrix not log
        for j in range(0,len(Popt[select_parameters])):
            if j in indlt:
                samples_matrix_not_log[0,:j]=exp(Popt[j])
        samples_matrix_not_log[1:,:-1]=samples_not_log[:,:]#because LHS returns non log transformed P        
        
        #fill in samples matrix log
        samples_matrix_log[0,:-1]=Popt[select_parameters]
        for i in range(1,NL):
            for j in range(0,len(Popt[select_parameters])):
                if j in indlt:
                    samples_matrix_log[i,j]=log(samples_matrix_not_log[i,j])
                else:
                    samples_matrix_log[i,j]=samples_matrix_not_log[i,j]
       
        
        for i in range(0,NL):
            Psample=empty(len(P0))
            Psample[:]=P0
            realisation=samples_matrix_log[i,:-1] 
            Psample[select_parameters]=realisation

            flags['SIMULATE']=1
            r=response(Psample,data,stress_preprocess,time_step,P_ind,flags,Nint,select_data,select_parameters,logtransform,stress_list,derivative=derivative,delp=delp)
            flags['SIMULATE']=0

            simulation_det=r[1][mask_y]#deterministic simulation
            err_det=y-simulation_det             #residuals
            err_det=dot(diag(weights),err_det)
            SSreg_det=sum(pow(err_det,2))            

            observed_deviations_from_mean=y-mean(y)
            observed_deviations_from_mean=dot(diag(weights),observed_deviations_from_mean)
            SStot=sum(pow(observed_deviations_from_mean,2))
            expvar=100*(1-SSreg_det/SStot)
            score=expvar

            if flags['NOISE']==1:
                simulation_stoch=r[4][mask_y]#stochastic simulation
                SSWI_weights=r[5]        
                err_stoch=y-simulation_stoch         #innovations
                err_stoch=multiply(err_stoch,SSWI_weights) #weighted innovations
                err_tot=err_det+err_stoch      #residuals plus innovations    
                SSregold_tot=sum(pow(err_tot,2))     #sum squared errors adding  residuals plus innovations      
                 
            
            if flags['FIT HARMONIC COMPONENT'] in [1,2]:#added 30-9-2017  ## #0006
                if flags['FIT HARMONIC COMPONENT']==1:
                    nb=14 #nb is the output number in the function response()
                elif flags['FIT HARMONIC COMPONENT']==2:
                    nb=15
                #shapeJ=shape(J)
                # NL=shapeJ[0]
                # NC=shapeJ[1]
                weights_simul=.1#weights attributed to simulated heads                  #0003$  #0004$  #0005$  
                weights_hc=1.#weights attributed to harmonic componenent #$
        
                weights_extended=empty(2*len(y))
                weights_extended[:len(y)]=weights_simul
                weights_extended[len(y):]=weights_hc                
                
                y_extended=empty(2*len(y))
                simulation_det_extended=empty(2*len(y))
                hc_obs=data['H_OBS']['hc'][:,1]##$  
                mean_level_hc_obs=data['H_OBS']['mean level hc_hobs']
                if flags['FIT HARMONIC COMPONENT']==2:
                    hc_obs=hc_obs-mean_level_hc_obs     #this is because in the case of the harmonic component derived from convolution of PIII with harmonic component of evap, the base level is zero                
                hc_obs=hc_obs[mask_y]
                hc_sim_ls=r[14]#this is the harmonic component least square fitted
                hc_sim=r[nb][:,1]
                hc_sim=hc_sim[mask_y] 
                y_extended[:len(y)]=y
                y_extended[len(y):]=hc_obs          
                simulation_det_extended[:len(y)]=simulation_det
                simulation_det_extended[len(y):]=hc_sim  
                errold_det_extended=y_extended-simulation_det_extended
                observed_deviations_from_mean_extended=y_extended-mean(y_extended)
                observed_deviations_from_mean_extended=dot(diag(weights_extended),observed_deviations_from_mean_extended)                
                SStot_extended=sum(pow(observed_deviations_from_mean_extended,2))                
                
                
                SSreg_det_extended=sum(pow(errold_det_extended,2)) 
                expvar_extended=100*(1-SSreg_det_extended/SStot_extended)  
                score=expvar_extended
                
            samples_matrix_log[i,-1]=score
            samples_matrix_not_log[i,-1]=score
    
        alfa=0.05 #0005
